fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Each special guest consumes one cookie from each pile,
    // and each regular guest consumes one cookie from either pile.
    // We need:
    // 1. a >= m and b >= m, so we can give each special guest one from each pile.
    // 2. a + b >= n + 2*m, so we have enough cookies in total.
    let total_available = a as u16 + b as u16;
    let total_needed = n as u16 + (m as u16) * 2;
    total_available >= total_needed && a >= m && b >= m
}